from dataclasses import dataclass
from datetime import date


@dataclass
class Kitap:
    id: int
    ad: str
    yazar: str


@dataclass
class Uye:
    id: int
    ad: str
    tur: str = "standart"  # "standart" ya da "ogrenci"


@dataclass
class Odunc:
    kitap_id: int
    uye_id: int
    alinma: date
    iade: date | None = None
    ceza: float = 0.0

from datetime import date
from .modeller import Odunc


class KutuphaneServisi:
    # Üye türlerine göre maksimum ödünç sayısı
    MAX_ODUNC = {"standart": 3, "ogrenci": 5}

    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next(
            (k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None),
            None,
        )

    def _ceza_hesapla(self, uye, alinma, iade):
        """İade cezasını hesapla."""
        gecikme_gun = (iade - alinma).days - 14
        if gecikme_gun <= 0:
            return 0.0

        if gecikme_gun <= 7:
            ceza = gecikme_gun * 2.50
        else:
            ceza = 7 * 2.50 + (gecikme_gun - 7) * 5.00

        # Maksimum ceza sınırı
        if ceza > 150.0:
            ceza = 150.0

        # Öğrenci indirimi
        if uye.tur == "ogrenci":
            ceza *= 0.5

        return round(ceza, 2)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")

        uye = self.uyeler[uye_id]
        aktif_sayisi = len(
            [
                k
                for k in self.kayitlar
                if k.uye_id == uye_id and k.iade is None
            ]
        )
        max_odunc = self.MAX_ODUNC.get(uye.tur, 3)
        if aktif_sayisi >= max_odunc:
            raise ValueError(f"ödünç sınırı aşıldı (max {max_odunc})")

        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")
        uye = self.uyeler[kayit.uye_id]
        ceza = self._ceza_hesapla(uye, kayit.alinma, tarih)
        kayit.iade = tarih
        kayit.ceza = ceza
        return kayit

    def toplam_ceza(self, uye_id):
        """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
        return round(
            sum(
                k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None
            ),
            2,
        )

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

